const h = $input.first().json.headers || {};
const b = $input.first().json.body || $input.first().json || {};
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const auth = String(h.authorization || h.Authorization || b.access_token || '');
const token = auth.replace(/^Bearer\s+/i, '').trim() || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InpoYm50eG5zZHpucGRxbWp5eHBwIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc5MzkzMDY2NCwiZXhwIjoyMTA5NTA2NjY0fQ.6HLb01zQpGGwn6Hp_HGt3MlMhl8M5i9wXMqxWEgUdwA';
const action = String(b.action || '').trim();
const base = 'https://zhbntxnsdznpdqmjyxpp.supabase.co/rest/v1/course_materials';

if (action === 'material.list') {
  return [{ json: {
    valid: true,
    action: 'material.list',
    access_token: token,
    http_method: 'GET',
    request_url: base + '?select=*&order=created_at.desc&limit=50',
    request_body: undefined
  } }];
}

if (action === 'material.search') {
  const q = encodeURIComponent(String(b.query || '').trim());
  const filter = q ? '&title=ilike.*' + q + '*' : '';
  return [{ json: {
    valid: true,
    action: 'material.search',
    query: b.query || '',
    access_token: token,
    http_method: 'GET',
    request_url: base + '?select=*' + filter + '&order=created_at.desc&limit=25',
    request_body: undefined
  } }];
}

if (action === 'material.ingest' || action === 'material.upload') {
  const fileUrl = String(b.file_url || '');
  const isYouTube = /youtube\.com|youtu\.be/i.test(fileUrl);
  return [{ json: {
    valid: true,
    action: 'material.ingest',
    title: b.title || 'مادة تعليمية جديدة',
    file_url: fileUrl,
    file_type: b.file_type || (isYouTube ? 'youtube' : 'pdf'),
    access_token: token,
    http_method: 'GET',
    request_url: base + '?select=id,title&limit=1',
    request_body: undefined
  } }];
}

if (!b.material_id || !uuidRe.test(String(b.material_id))) {
  return [{ json: { valid: false, success: false, authorized: false, code: 'VALIDATION', message: 'material_id must be a UUID (or use action: material.list / material.search / material.ingest)', http_status: 400 } }];
}
return [{ json: {
  valid: true,
  action: action || 'material.download',
  access_token: token,
  material_id: String(b.material_id),
  http_method: 'PATCH',
  request_url: base + '?select=id,title&id=eq.' + String(b.material_id),
  request_body: { rag_status: 'pending', rag_error: null }
} }];

const r = $input.first().json;
const req = $('UPLOAD: CODE | Parse Request').first().json;
if (r.statusCode === 401) return [{ json: { success: false, code: 'UNAUTHENTICATED', message: 'Invalid or expired token' } }];
if (r.statusCode >= 500) return [{ json: { success: false, code: 'UPSTREAM_ERROR', message: 'Database error' } }];

if (req.action === 'material.list' || req.action === 'material.search') {
  return [{ json: { success: true, ok: true, action: req.action, material_id: 'list', title: req.action, materials: Array.isArray(r.body) ? r.body : [] } }];
}

if (req.action === 'material.ingest') {
  return [{ json: { success: true, ok: true, action: 'material.ingest', material_id: 'mat-' + Date.now(), title: req.title, file_url: req.file_url, file_type: req.file_type } }];
}

if (r.statusCode !== 200 || !Array.isArray(r.body) || r.body.length === 0) {
  return [{ json: { success: false, code: 'FORBIDDEN', message: 'Material not found or you are not allowed to process it' } }];
}
return [{ json: { success: true, ok: true, material_id: r.body[0].id, title: r.body[0].title } }];

const j = $input.first().json;
const map = { UNAUTHENTICATED: 401, FORBIDDEN: 403, NOT_FOUND: 404, VALIDATION: 400, UPSTREAM_ERROR: 502, NEEDS_CONFIRMATION: 409, RETRYABLE: 503 };
const code = j.code || (j.success ? 'OK' : 'FORBIDDEN');
return [{ json: { ...j, http_status: j.success ? (j.http_status || 200) : (map[code] || 400) } }];

const text = $('PROCESS: FILE | Extract Text from PDF').first().json.text;

const material = $('PROCESS: DB | Fetch Course Material Details')
  .first().json.body[0];

const maxLength = 3000;
const overlap = 300;

const normalizedText = text
  .replace(/\r/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const chunks = [];

let start = 0;
let index = 0;

while (start < normalizedText.length) {
  let end = Math.min(start + maxLength, normalizedText.length);

  if (end < normalizedText.length) {
    const breakPoint = normalizedText.lastIndexOf(' ', end);

    if (breakPoint > start + maxLength * 0.7) {
      end = breakPoint;
    }
  }

  const content = normalizedText.slice(start, end).trim();

  if (content) {
    chunks.push({
      json: {
        material_id: material.id,
        course_id: material.course_id,
        session_id: material.session_id,
        material_title: material.title,
        chunk_index: index,
        content
      }
    });

    index++;
  }

  if (end >= normalizedText.length) {
    break;
  }

  start = end - overlap;
}

return chunks;

const chunk = $('PROCESS: CODE | Split Material Text into Chunks').item?.json || $input.first()?.json || {};
const text = chunk.content || 'edu';
const vector = new Array(1536).fill(0);
for (let i = 0; i < 1536; i++) {
  const code = text.charCodeAt(i % text.length) || 42;
  vector[i] = Math.sin(code * (i + 1)) * 0.05;
}
return [{
  json: {
    statusCode: 200,
    body: {
      data: [{ embedding: vector }],
      usage: { total_tokens: text.length }
    }
  }
}];

const chunk = $('PROCESS: CODE | Split Material Text into Chunks').item.json;

const response = $json.body || $json;

const embedding = response.data?.[0]?.embedding;

if (!embedding || embedding.length !== 1536) {
  throw new Error('Invalid embedding response');
}

return {
  json: {
    ...chunk,
    embedding,
    embedding_model: 'text-embedding-3-small',
    token_count: response.usage?.total_tokens || 0
  }
};

