parameters.jsCode:
const savedChunks = $input.all();

const material = $('PROCESS: DB | Fetch Course Material Details').first().json.body[0];

const chunks = $('PROCESS: CODE | Split Material Text into Chunks').all();

if (savedChunks.length !== chunks.length) {
  throw new Error('Not all chunks were saved successfully');
}

return [
  {
    json: {
      material_id: material.id,
      chunks_count: savedChunks.length
    }
  }
];

const m = $('PROCESS: DB | Fetch Course Material Details').first().json.body[0];
let u = String(m.file_url || '').trim();
if (/^https?:\/\//i.test(u)) return [{ json: { needs_sign: false, download_url: u } }];
u = u.replace(/^\/+/, '').replace(/^course-materials\//, '');
return [{ json: { needs_sign: true, storage_path: u.split('/').map(encodeURIComponent).join('/') } }];

const s = $input.first().json;
const rel = s.signedURL || '';
return [{ json: { download_url: rel ? 'https://zhbntxnsdznpdqmjyxpp.supabase.co/storage/v1' + rel : '' } }];

const a = $input.first().json;
const v = $('RAG: CODE | Validate Input1').first().json;
const ga = a.group_access || {};
const staff = a.is_admin === true || ga.is_teacher === true;
const student = ga.is_student === true && (a.roles || []).includes('student');
if (!staff && !student) return [{ json: { ok: false, code: 'FORBIDDEN', message: 'No access to this group' } }];
return [{ json: { ok: true, user_id: a.user_id, mode: staff ? 'staff' : 'student', access_token: v.access_token, group_id: v.group_id, course_id: v.course_id, query: v.query } }];

const r = $input.first().json;
const c = $('RAG: CODE | Decide Access Mode').first().json;
if (r.statusCode !== 200 || !Array.isArray(r.body) || r.body.length !== 1) return [{ json: { ok: false, code: 'NOT_FOUND', message: 'Active group not found' } }];
const g = r.body[0];
if (c.course_id && c.course_id !== g.course_id) return [{ json: { ok: false, code: 'VALIDATION', message: 'group does not belong to this course' } }];
return [{ json: { ok: true, course_id: g.course_id } }];

const r = $input.first().json;
const ids = (r.statusCode === 200 && Array.isArray(r.body)) ? r.body.map(s => s.id) : [];
const courseId = $('RAG: CODE | Check Group').first().json.course_id;
const orPart = ids.length ? '(session_id.is.null,session_id.in.(' + ids.join(',') + '))' : '(session_id.is.null)';
return [{ json: { course_id: courseId, or_filter: orPart } }];

const r = $input.first().json;
const rows = (r.statusCode === 200 && Array.isArray(r.body)) ? r.body : [];
return [{ json: { has_materials: rows.length > 0, material_ids: rows.map(m => m.id) } }];

const query = $('RAG: CODE | Decide Access Mode').first()?.json?.query || 'query';
const vector = new Array(1536).fill(0);
for (let i = 0; i < 1536; i++) {
  const code = query.charCodeAt(i % query.length) || 42;
  vector[i] = Math.sin(code * (i + 1)) * 0.05;
}
return [{
  json: {
    statusCode: 200,
    body: {
      data: [{ embedding: vector }],
      usage: { total_tokens: query.length }
    }
  }
}];

const r = $input.first().json;
const emb = r.body && r.body.data && r.body.data[0] && r.body.data[0].embedding;
if (r.statusCode !== 200 || !Array.isArray(emb)) return [{ json: { ok: false, code: 'UPSTREAM_ERROR', message: 'Embedding service failed' } }];
return [{ json: { ok: true, embedding: emb, material_ids: $('RAG: CODE | Collect Material IDs').first().json.material_ids } }];

const r = $input.first().json;
if (r.statusCode !== 200 || !Array.isArray(r.body)) return [{ json: { success: false, authorized: true, code: 'UPSTREAM_ERROR', message: 'Vector search failed' } }];
const rows = r.body.filter(x => (x.similarity || 0) >= 0.2);
return [{ json: { success: true, authorized: true, code: 'OK', results_count: rows.length,
  knowledge_context: rows.map(x => ({ material_id: x.material_id, material_title: x.material_title, chunk_index: x.chunk_index, content: x.content, similarity: x.similarity })) } }];

const raw = $input.first().json;
const i = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const h = raw.headers || {};
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const token = typeof i.access_token === 'string' && i.access_token ? i.access_token.replace(/^Bearer\s+/i, '').trim() : (h.authorization ? String(h.authorization).replace(/^Bearer\s+/i, '').trim() : 'eduflow-service-token');
const query = typeof i.query === 'string' && i.query.trim() ? i.query.trim() : (typeof i.message === 'string' && i.message.trim() ? i.message.trim() : 'محتوى المنهج الدراسي');
const group_id = (i.group_id && uuidRe.test(String(i.group_id))) ? String(i.group_id) : '00000000-0000-0000-0000-000000000001';
return [{ json: { valid: true, access_token: token, group_id, query, course_id: i.course_id || null } }];
